export function figmaPluginMain(){
 const ns='pixelMill',clone=value=>JSON.parse(JSON.stringify(value)),identity=[[1,0,0],[0,1,0]];
 const set=(node,key,value)=>{const text=JSON.stringify(value),old=Number(node.getSharedPluginData(ns,key+'Count'))||0,count=Math.ceil(text.length/16000);for(let i=0;i<count;i++)node.setSharedPluginData(ns,key+i,text.slice(i*16000,(i+1)*16000));for(let i=count;i<old;i++)node.setSharedPluginData(ns,key+i,'');node.setSharedPluginData(ns,key+'Count',String(count))};
 const get=(node,key)=>{if(!node)return null;const count=Number(node.getSharedPluginData(ns,key+'Count'));if(!Number.isInteger(count)||count<1||count>10000)return null;let text='';for(let i=0;i<count;i++)text+=node.getSharedPluginData(ns,key+i);return JSON.parse(text)};
 const image=src=>figma.createImage(figma.base64Decode(src.split(',')[1])).hash;
 const paint=hash=>[{type:'IMAGE',imageHash:hash,scaleMode:'CROP',imageTransform:identity}];
 const color=hex=>{const n=parseInt((hex||'#ffffff').slice(1),16);return[{type:'SOLID',color:{r:(n>>16&255)/255,g:(n>>8&255)/255,b:(n&255)/255}}]};
 const multiply=(a,b)=>[[a[0][0]*b[0][0]+a[0][1]*b[1][0],a[0][0]*b[0][1]+a[0][1]*b[1][1],a[0][0]*b[0][2]+a[0][1]*b[1][2]+a[0][2]],[a[1][0]*b[0][0]+a[1][1]*b[1][0],a[1][0]*b[0][1]+a[1][1]*b[1][1],a[1][0]*b[0][2]+a[1][1]*b[1][2]+a[1][2]]];
 function inverse(m){const d=m[0][0]*m[1][1]-m[0][1]*m[1][0];if(Math.abs(d)<1e-8)throw Error('A frame has no usable transform.');return[[m[1][1]/d,-m[0][1]/d,(m[0][1]*m[1][2]-m[1][1]*m[0][2])/d],[-m[1][0]/d,m[0][0]/d,(m[1][0]*m[0][2]-m[0][0]*m[1][2])/d]]}
 function position(node,o,b){const a=(o.rotation||0)*Math.PI/180,c=Math.cos(a),s=Math.sin(a),f=o.flip?-1:1;node.relativeTransform=[[c*f,-s,o.x-b.x+o.w/2-c*f*o.w/2+s*o.h/2],[s*f,c,o.y-b.y+o.h/2-s*f*o.w/2-c*o.h/2]]}
 function geometry(node,root,b){const m=multiply(inverse(root.absoluteTransform),node.absoluteTransform),sx=Math.hypot(m[0][0],m[1][0]),sy=Math.hypot(m[0][1],m[1][1]),dot=m[0][0]*m[0][1]+m[1][0]*m[1][1];if(Math.abs(dot)>1e-5||sx<1e-6||sy<1e-6)throw Error('Remove skew from '+node.name+' before exporting.');const flip=m[0][0]*m[1][1]-m[0][1]*m[1][0]<0,w=node.width*sx,h=node.height*sy,rotation=Math.atan2(-m[0][1]/sy,m[1][1]/sy)*180/Math.PI;return{x:b.x+m[0][2]+m[0][0]*node.width/2+m[0][1]*node.height/2-w/2,y:b.y+m[1][2]+m[1][0]*node.width/2+m[1][1]*node.height/2-h/2,w,h,rotation,flip}}
 function signature(node){const child=n=>({type:['COMPONENT','INSTANCE'].includes(n.type)?'COMPONENT':n.type,fills:n.fills,strokes:n.strokes,strokeWeight:n.strokeWeight,effects:n.effects,cornerRadius:n.cornerRadius,vectorPaths:n.vectorPaths,characters:n.characters,children:n.children?.map(c=>({x:c.x/n.width,y:c.y/n.height,w:c.width/n.width,h:c.height/n.height,rotation:c.rotation,opacity:c.opacity,visible:c.visible,visual:child(c)}))});return JSON.stringify(child(node))}
 function component(parent,name,w,h,hash,meta){const c=figma.createComponent();parent.appendChild(c);c.name=name;c.resize(w,h);c.fills=paint(hash);c.clipsContent=true;set(c,'component',meta);return c}
 function check(data){const p=data?.project;if(data?.format!=='pixel-mill-figma'||data.version!==1||p?.format!=='max-level-studio'||p.version!==1||!Array.isArray(p.objects)||!Array.isArray(p.assets)||p.objects.length>5000||p.assets.length>2000||!Array.isArray(data.rasters)||!Array.isArray(data.appearances)||!data.bounds)throw Error('Choose level.figma.json from a Pixel Mill Figma kit.');for(const o of p.objects)if(!['x','y','w','h'].every(k=>Number.isFinite(o[k]))||o.w<1||o.h<1||o.w>8192||o.h>8192)throw Error('Invalid piece dimensions.');for(const a of [...p.assets,...data.rasters,...data.appearances])if(a.src&&!/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(a.src))throw Error('Only embedded PNG images are supported.');for(const k of ['x','y','w','h'])if(!Number.isFinite(data.bounds[k]))throw Error('Invalid level bounds.')}
 async function importLevel(data){
  check(data);const p=clone(data.project),b=data.bounds,page=figma.currentPage,library=figma.createFrame(),root=figma.createFrame();
  try{
   page.appendChild(library);page.appendChild(root);library.name=p.name+' / Components';library.fills=[];library.clipsContent=false;library.x=b.w+128;library.resize(1024,64);root.name=p.name;root.fills=[];root.clipsContent=false;root.resize(Math.max(1,b.w),Math.max(1,b.h));root.x=0;root.y=Math.max(0,...page.children.filter(n=>n!==root&&n!==library).map(n=>n.y+n.height+160));library.y=root.y;
   const sources={},components=new Map(),variants=new Map();let x=0,y=0,rowHeight=0;
   const arrange=c=>{if(x&&x+c.width>1024){x=0;y+=rowHeight+48;rowHeight=0}c.x=x;c.y=y;x+=c.width+32;rowHeight=Math.max(rowHeight,c.height)};
   for(const a of p.assets)if(a.src){sources[a.id]=image(a.src);const archive=figma.createRectangle();library.appendChild(archive);archive.name='Source / '+a.name;archive.resize(a.w,a.h);archive.fills=paint(sources[a.id]);archive.visible=false;archive.locked=true;delete a.src}
   for(const a of data.rasters){const meta=p.assets.find(item=>item.id===a.id);if(!meta)throw Error('An asset reference is missing.');const c=component(library,'Assets / '+meta.name,a.w,a.h,image(a.src),{assetId:a.id});arrange(c);components.set(a.id,c)}
   for(const a of data.appearances){if(a.reuse){if(!variants.has(a.reuse))throw Error('An appearance reference is missing.');variants.set(a.id,variants.get(a.reuse));continue}const o=p.objects.find(o=>o.id===a.id);const c=component(library,'Appearances / '+(o?.name||a.id),a.w,a.h,image(a.src),{objectId:a.id});arrange(c);variants.set(a.id,c)}
   for(const o of p.objects){let node;if(o.collisionOnly){node=figma.createFrame();node.resize(o.w,o.h);node.fills=[];node.clipsContent=false;const line=figma.createVector();node.appendChild(line);line.vectorPaths=[{windingRule:'NONZERO',data:o.points.map((v,i)=>(i?'L ':'M ')+v.x+' '+v.y).join(' ')}];line.fills=[];line.strokes=color('#ff6538');line.strokeWeight=o.brushWidth;line.strokeCap='ROUND';line.constraints={horizontal:'SCALE',vertical:'SCALE'}}else if(variants.has(o.id))node=variants.get(o.id).createInstance();else if(o.asset){const c=components.get(o.asset);if(!c)throw Error('A placed asset is missing.');node=c.createInstance()}else{node=figma.createRectangle();node.fills=color(o.color)}root.appendChild(node);node.resize(o.w,o.h);node.name=o.name;node.opacity=o.opacity??1;position(node,o,b);set(node,'object',o);set(node,'visual',signature(node));node.locked=!!o.locked}
   const spawn=figma.createEllipse();root.appendChild(spawn);spawn.name='Spawn';spawn.resize(8,8);spawn.x=p.spawn.x-b.x-4;spawn.y=p.spawn.y-b.y-4;spawn.fills=color('#91e8c1');spawn.strokes=color('#111111');spawn.strokeWeight=1;set(spawn,'spawn',true);
   library.resize(Math.max(1024,...library.children.map(c=>c.x+c.width)),Math.max(64,y+rowHeight));
   for(const c of library.children)set(c,'visual',signature(c));set(root,'level',{base:p,sources,bounds:b,library:library.id});
   page.selection=[root];figma.viewport.scrollAndZoomIntoView([root]);figma.commitUndo();return p.objects.length+' editable pieces and '+(components.size+new Set(variants.values()).size)+' components imported.';
  }catch(error){root.remove();library.remove();throw error}
 }
 function levelRoot(){for(const selected of figma.currentPage.selection){let n=selected;while(n&&n.type!=='PAGE'){if(get(n,'level'))return n;n=n.parent}}const candidates=figma.currentPage.children.filter(n=>get(n,'level'));if(candidates.length===1)return candidates[0];throw Error('Select a Pixel Mill Level frame first.')}
 async function png(node){const copy=node.clone(),frame=figma.createFrame();try{frame.fills=[];frame.clipsContent=true;frame.resize(Math.ceil(node.width),Math.ceil(node.height));copy.locked=false;frame.appendChild(copy);copy.relativeTransform=identity;copy.opacity=1;copy.visible=true;const bytes=await frame.exportAsync({format:'PNG',constraint:{type:'SCALE',value:1}});return'data:image/png;base64,'+figma.base64Encode(bytes)}finally{frame.remove();if(!copy.removed)copy.remove()}}
 async function exportLevel(){
  const root=levelRoot(),meta=get(root,'level'),base=clone(meta.base),b=meta.bounds;
  for(const a of base.assets)if(meta.sources[a.id]){const source=figma.getImageByHash(meta.sources[a.id]);if(!source)throw Error('An original image is missing. Reimport the source kit into a new frame.');a.src='data:image/png;base64,'+figma.base64Encode(await source.getBytesAsync())}
  const project=clone(base);project.name=root.name.slice(0,80);project.objects=[];
  const used=new Set(),assetsByVisual=new Map(),newAssetIds=new Set(project.assets.map(a=>a.id)),library=await figma.getNodeByIdAsync(meta.library);let serial=0,spawnCount=0;
  const assetId=()=>{let id;do{id='figma-'+root.id.replace(/[^a-zA-Z0-9]/g,'_')+'-'+(++serial)}while(newAssetIds.has(id));newAssetIds.add(id);return id};
  const appearance=async(node)=>{const key=signature(node)+'|'+node.width+'|'+node.height;if(assetsByVisual.has(key))return assetsByVisual.get(key);if(node.width>4096||node.height>4096||node.width*node.height>16000000)throw Error('New or repainted artwork must be at most 4096 pixels per side. Split '+node.name+' before exporting.');const id=assetId(),src=await png(node);project.assets.push({id,name:node.name.slice(0,80),w:Math.ceil(node.width),h:Math.ceil(node.height),src});assetsByVisual.set(key,id);return id};
  if(library)for(const component of library.children){const c=get(component,'component');if(c?.assetId){const asset=project.assets.find(a=>a.id===c.assetId);if(asset)asset.name=component.name.replace(/^Assets \/ /,'').slice(0,80);if(get(component,'visual')!==signature(component))await appearance(component)}}
  const hasPieces=nodes=>nodes.some(n=>get(n,'object')||get(n,'spawn')||n.children&&hasPieces(n.children));const visibility=node=>{let opacity=1;for(let n=node;n&&n!==root;n=n.parent){if(n.visible===false)return 0;opacity*=n.opacity??1}return opacity};
  const walk=async nodes=>{for(const node of nodes){if(get(node,'spawn')){spawnCount++;const g=geometry(node,root,b);project.spawn={x:g.x+g.w/2,y:g.y+g.h/2};for(const k of ['x','y'])if(Math.abs(project.spawn[k]-base.spawn[k])<1e-6)project.spawn[k]=base.spawn[k];continue}const sourceComponent=node.type==='INSTANCE'?await node.getMainComponentAsync():null,template=get(sourceComponent,'component'),stored=get(node,'object'),original=stored||template?.objectId&&base.objects.find(o=>o.id===template.objectId);if(!original&&node.children&&hasPieces(node.children)){await walk(node.children);continue}if(!('width'in node))continue;const g=geometry(node,root,b);for(const k of ['x','y','w','h','rotation'])g[k]=original&&Math.abs(g[k]-(original[k]||0))<1e-6?original[k]||0:Math.round(g[k]*1e6)/1e6;const o=original?clone(original):{id:'figma-object-'+node.id.replace(/[^a-zA-Z0-9]/g,'_'),asset:null,inset:0,kind:get(node,'kind')||'decor',crop:null,opacity:1};if(!stored||used.has(o.id))o.id='figma-object-'+node.id.replace(/[^a-zA-Z0-9]/g,'_');used.add(o.id);
    if(o.collisionOnly){const sx=g.w/o.w,sy=g.h/o.h;if(Math.abs(sx-sy)>1e-5||Math.abs(g.rotation)>1e-5||g.flip)throw Error('Painted collision can move or scale uniformly. Keep its rotation and reflection unchanged.');o.points=o.points.map(p=>({x:p.x*sx,y:p.y*sy}));o.brushWidth*=sx}
    let fillOpacity=1;const changed=original&&(get(node,'visual')||get(sourceComponent,'visual'))!==signature(node);o.kind=get(node,'kind')||o.kind;
    if(!o.collisionOnly&&(changed||!original)){let c=null;if(node.type==='INSTANCE')c=get(await node.getMainComponentAsync(),'component');const fill=Array.isArray(node.fills)&&node.fills.length===1?node.fills[0]:null;
     if(!changed&&c?.assetId&&base.assets.some(a=>a.id===c.assetId)&&library?.children.some(a=>get(a,'component')?.assetId===c.assetId&&get(a,'visual')===signature(a))){o.asset=c.assetId}
     else if(node.type==='RECTANGLE'&&fill?.type==='SOLID'&&!node.effects?.length&&!node.strokes?.length&&!node.cornerRadius){o.asset=null;fillOpacity=fill.opacity??1;o.color='#'+[fill.color.r,fill.color.g,fill.color.b].map(v=>Math.round(v*255).toString(16).padStart(2,'0')).join('')}
     else{o.asset=await appearance(node);delete o.color}
     delete o.artwork;delete o.adjust;o.crop=null;
    }
    o.inset=Math.min(g.h-1,(o.inset||0)*g.h/(original?.h||g.h));Object.assign(o,g,{name:node.name.slice(0,80),opacity:visibility(node)*fillOpacity,locked:!!node.locked});project.objects.push(o);
   }};
  await walk(root.children);if(spawnCount!==1)throw Error('Keep exactly one Spawn marker in the Level frame.');if(project.assets.length>2000||project.objects.length>5000)throw Error('This level exceeds Pixel Mill project limits. Split it into smaller projects.');return{format:'pixel-mill-figma-return',version:1,base,project};
 }
 figma.showUI(__html__,{width:380,height:430,themeColors:true});let busy=false;
 figma.ui.onmessage=async message=>{if(busy)return;busy=true;try{
  if(message.type==='import'){const text=await importLevel(message.data);figma.ui.postMessage({type:'status',text})}
  else if(message.type==='export'){const data=await exportLevel();figma.ui.postMessage({type:'download',data,name:data.project.name+'.figma-return.json'})}
  else if(message.type==='kind'){if(!['solid','platform','ladder','decor'].includes(message.kind))throw Error('Choose a collision type.');let count=0;for(const pick of figma.currentPage.selection){let selected=pick;while(selected?.parent&&selected.parent.type!=='PAGE'&&!get(selected,'object')&&!get(selected.parent,'level'))selected=selected.parent;if(!selected?.parent||selected.parent.type==='PAGE'||get(selected,'level')||get(selected,'spawn'))continue;const o=get(selected,'object');if(o?.collisionOnly)continue;if(o){o.kind=message.kind;set(selected,'object',o)}else set(selected,'kind',message.kind);count++}if(!count)throw Error('Select pieces inside the Level frame.');figma.commitUndo();figma.ui.postMessage({type:'status',text:count+' pieces set to '+message.kind+'.'})}
 }catch(error){figma.ui.postMessage({type:'error',text:error.message||String(error)})}finally{busy=false;figma.ui.postMessage({type:'ready'})}};
}

export const figmaPluginUI=`<!doctype html><html><head><meta charset="utf-8"><style>body{font:13px/1.5 system-ui;margin:20px;background:var(--figma-color-bg,#fff);color:var(--figma-color-text,#222)}h1{font-size:20px;margin:0 0 8px}p{margin:8px 0 16px}button,select{font:inherit;min-height:40px;border:1px solid #8886;border-radius:8px;padding:8px 12px;background:var(--figma-color-bg-secondary,#eee);color:inherit}button{cursor:pointer}button:disabled{opacity:.5}#import,#export{width:100%;margin-bottom:12px}label{display:block}#status{white-space:pre-wrap;overflow-wrap:anywhere}small{display:block;opacity:.7}</style></head><body><h1>Pixel Mill Bridge</h1><p>Reusable components and playable level geometry.</p><button id="import">Import Pixel Mill kit JSON</button><input id="file" type="file" accept=".json" hidden><button id="export">Export back to Pixel Mill</button><label>Selected pieces <select id="kind"><option value="decor">Decoration</option><option value="solid">Solid</option><option value="platform">One-way platform</option><option value="ladder">Ladder</option></select> <button id="apply">Apply</button></label><p id="status" role="status">Import creates a separate snapshot. Select its Level frame when exporting.</p><small>No network access. Original sources and game data stay in the file.</small><script>
const buttons=[...document.querySelectorAll('button')],status=document.getElementById('status');function send(message){buttons.forEach(b=>b.disabled=true);status.textContent='Working…';parent.postMessage({pluginMessage:message},'*')}
document.getElementById('import').onclick=()=>document.getElementById('file').click();document.getElementById('file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100*1024*1024)throw Error('Choose a kit under 100 MB.');send({type:'import',data:JSON.parse(await file.text())})}catch(error){status.textContent=error.message}finally{e.target.value=''}};document.getElementById('export').onclick=()=>send({type:'export'});document.getElementById('apply').onclick=()=>send({type:'kind',kind:document.getElementById('kind').value});onmessage=e=>{const m=e.data.pluginMessage;if(!m)return;if(m.type==='ready')buttons.forEach(b=>b.disabled=false);if(m.text)status.textContent=m.text;if(m.type==='download'){const url=URL.createObjectURL(new Blob([JSON.stringify(m.data)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=m.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);status.textContent='Return JSON ready. In Pixel Mill choose Figma import / export → Import changes.'}};
</script></body></html>`;
